/* ── 스크래퍼 차단 ──────────────────────────────────────────
   라우팅·렌더링 전에 끊는다. 계정에 WAF 쓰기 권한이 없어 워커에서 처리한다.
   185.218.86.11 = TC DATACENTER LIMITED (AMS 경유). 1시간에 2만 요청,
   위장 UA Firefox/47.0, PUT 남발로 504 를 유발했다.
   허용 메서드는 GET/POST/HEAD/OPTIONS 뿐이다. */
const BLOCK_IPS = new Set(["185.218.86.11"]);
const BLOCK_UA_RE = /Firefox\/47\.0\b/i;
const ALLOWED_METHODS = new Set(["GET", "POST", "HEAD", "OPTIONS"]);
function blockScraper(request){
  const nostore = { "cache-control": "no-store" };
  if(!ALLOWED_METHODS.has(request.method))
    return new Response("Method Not Allowed", { status: 405, headers: Object.assign({ "allow": "GET, POST, HEAD, OPTIONS" }, nostore) });
  if(BLOCK_IPS.has(request.headers.get("cf-connecting-ip") || ""))
    return new Response("Forbidden", { status: 403, headers: nostore });
  if(BLOCK_UA_RE.test(request.headers.get("user-agent") || ""))
    return new Response("Forbidden", { status: 403, headers: nostore });
  return null;
}

export default {
  /* 매일 1회 IndexNow 자동 제출. URL 이 많아 하루 1,000개씩 돌아가며 보낸다 */
  async scheduled(event, env, ctx){
    const all=indexnowUrls(), PER=1000;
    const day=Math.floor(Date.now()/86400000);
    const start=all.length?(day*PER)%all.length:0;
    ctx.waitUntil(submitIndexNow(all.slice(start,start+PER)));
  },
  async fetch(request, env, ctx){
    const __blk = blockScraper(request); if(__blk) return __blk;
    const url=new URL(request.url);
    const path=url.pathname.replace(/\/+$/,"")||"/";
    if(path==="/api/track"&&request.method==="POST"){try{const b=await request.json();
    /* 같은 방문자가 같은 버튼을 반복해 눌러도 1건만 기록·발송한다 */
    if (await tkDup(env, SITE_KEY, b.type, (b.page || '').slice(0, 300), request.headers.get('CF-Connecting-IP') || '')) {
      return new Response(JSON.stringify({ ok: true, dup: 1 }), { headers: { 'content-type': 'application/json', 'access-control-allow-origin': '*' } });
    }
const __ua=request.headers.get("User-Agent")||"";if(!TG_BOT_RE.test(__ua)&&TG_LABEL[b.type]){const __tg=tgNotify(env, b.type,(b.page||"/").slice(0,300),b.ref||"",__ua, String(b.b || "").slice(0, 40));if(ctx&&ctx.waitUntil)ctx.waitUntil(__tg);else await __tg;}const ip=request.headers.get("CF-Connecting-IP")||"";const ts=new Date().toISOString();if(env&&env.DB&&!(b.type==="view"&&BOT_UA_RE.test(request.headers.get("User-Agent")||"")||(b.type==="view"&&skipViewCf(request, request.headers.get("CF-Connecting-IP")||"")))&&(b.type==="tel"||b.type==="sms"||b.type==="contact"||b.type==="view")){await env.DB.prepare('INSERT INTO events (site,type,page,ref,ip,ts,ua,device,source,keyword) VALUES (?,?,?,?,?,?,?,?,?,?)')
            .bind(SITE_KEY, b.type, (b.page||'').slice(0,300), (b.ref||'').slice(0,120), ip, ts, ...tkMeta(request.headers.get('User-Agent')||'', b.ref||'', SITE_HOST)).run();}}catch(e){}return new Response(JSON.stringify({ok:true}),{headers:{"Content-Type":"application/json","Access-Control-Allow-Origin":"*"}});}
    if(path==="/api/track"&&request.method==="OPTIONS")return new Response(null,{headers:{"Access-Control-Allow-Origin":"*","Access-Control-Allow-Methods":"POST,OPTIONS","Access-Control-Allow-Headers":"Content-Type"}});
    /* 정적 HTML 경로만 엣지 캐시를 조회한다 (/api/track 등은 제외) */
    if(request.method === "GET" && (path === "/" || path === "/list" || path === "/region" || path === "/sitemap-regions" || path.startsWith("/region/"))){
      const __hit = await cachedHtmlHit(request);
      if(__hit) return __hit;
    }
    if(path==="/") return htmlRespCached(request, ctx, renderHome());
    if(path==="/"+INDEXNOW_KEY+".txt") return new Response(INDEXNOW_KEY,{headers:{"content-type":"text/plain; charset=UTF-8"}});
    if(path==="/indexnow/today"||path==="/indexnow/all"){
      if(url.searchParams.get("key")!==INDEXNOW_KEY) return new Response("forbidden",{status:403});
      const all=indexnowUrls(), PER=1000;
      const day=Math.floor(Date.now()/86400000);
      const st=all.length?(day*PER)%all.length:0;
      const list=path.endsWith("/all")?all:all.slice(st,st+PER);
      const res=await submitIndexNow(list);
      return new Response(JSON.stringify({requested:list.length,sent:res.sent,failed:res.failed,batches:res.batches,diag:res.diag}),{headers:{"content-type":"application/json; charset=UTF-8"}});
    }
    if(path==="/sitemap.xml") return sitemap(request, ctx);
    if(path==="/robots.txt") return robots();
    if(path==="/llms.txt") return llms();
    if(path==="/og.svg") return new Response(`<svg xmlns="http://www.w3.org/2000/svg" width="1200" height="630" viewBox="0 0 1200 630"><defs><linearGradient id="g" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#6E1228"/><stop offset="1" stop-color="#C9355A"/></linearGradient></defs><rect width="1200" height="630" fill="url(#g)"/><rect x="60" y="60" width="1080" height="510" rx="28" fill="none" stroke="rgba(255,255,255,.28)" stroke-width="2"/><text x="600" y="300" text-anchor="middle" font-family="Pretendard,'Apple SD Gothic Neo','Malgun Gothic',sans-serif" font-size="86" font-weight="800" fill="#ffffff">${SITE_NAME}</text><text x="600" y="378" text-anchor="middle" font-family="Pretendard,'Apple SD Gothic Neo','Malgun Gothic',sans-serif" font-size="34" font-weight="500" fill="rgba(255,255,255,.88)">전국 카드단말기 판매·설치</text><text x="600" y="530" text-anchor="middle" font-family="Pretendard,'Apple SD Gothic Neo','Malgun Gothic',sans-serif" font-size="28" font-weight="600" fill="rgba(255,255,255,.72)">${SITE_HOST}</text></svg>`,{headers:{"content-type":"image/svg+xml; charset=UTF-8","cache-control":"public, max-age=86400"}});
    if(path==="/favicon.svg") return new Response(FAVICON_SVG,{headers:{"content-type":"image/svg+xml; charset=UTF-8","cache-control":"public, max-age=604800"}});
    if(path==="/favicon.ico") return imgResp(FAV_ICO,"image/x-icon");
    if(path==="/favicon-32.png") return imgResp(FAV_P32,"image/png");
    if(path==="/favicon-192.png") return imgResp(FAV_P192,"image/png");
    if(path==="/apple-touch-icon.png"||path==="/apple-touch-icon-precomposed.png") return imgResp(FAV_P180,"image/png");
    if(path==="/atom.xml"||path==="/atom") return new Response(atomFromRss(await (rss()).text(), SITE+"/atom.xml"),{headers:{"content-type":"application/atom+xml; charset=UTF-8","cache-control":"public, max-age=3600"}});
    if(path==="/rss.xml"||path==="/rss") return rss();
    if(path==="/list") return htmlRespCached(request, ctx, renderList());
    if(path==="/region") return htmlRespCached(request, ctx, renderRegionIndex());
    if(path==="/sitemap-regions") return htmlRespCached(request, ctx, renderAllRegions());
    if(path.startsWith("/region/")){
      const seg=path.slice(8).split("/").filter(Boolean);
      if(seg.length===1){ const p=renderSido(seg[0]); if(p) return htmlRespCached(request, ctx, p); }
      else if(seg.length===2){ const p=renderGugun(seg[0],seg[1]); if(p) return htmlRespCached(request, ctx, p); }
      else if(seg.length===3){ const r=byDong.get(seg.join("/")); if(r) return htmlRespCached(request, ctx, renderDong(r)); }
    }
    return new Response("404 Not Found",{status:404,headers:{"content-type":"text/plain; charset=UTF-8"}});
  }
};
